// League outlook: playoff odds, power rankings and team shapes.
import * as api from '../../api.js';
import {createMemo,identity,rosterKey} from '../../cache.js';
import {leagueShape,leagueOutlook} from '../../league.js';
import {S} from '../state.js';
import {analysisHeader,chance,empty,esc,fmt,isLeagueView,isTradeView,league,oddsBar,ordinal,record,signed,teamCell} from '../core.js';
import {depthTable,positionBars,strengthScatter,teamRadar} from './charts.js';
import {render} from '../render.js';

export const leagueOutlooks=createMemo(6),rosterOutlooks=createMemo(12),projectionStamps=new WeakMap();
export function leagueSeasonKey(l=league()){return JSON.stringify([S.data.demo?'demo':S.data.user.user_id,S.data.nfl?.season,l?.league_id,S.data.week])}
export async function ensureLeagueSeason(force=false){
 const l=league();if(!l)return;const key=leagueSeasonKey(l);
 if(S.leagueSeasonState?.key===key&&!force&&(S.leagueSeasonState.loading||S.leagueSeasonState.past))return S.leagueSeasonState.done;
 // A retry after a failure keeps the message up instead of flashing the loading state every refresh.
 const retry=S.leagueSeasonState?.key===key?S.leagueSeasonState.error:null,state={key,loading:true,past:null,future:null,error:null,retry};S.leagueSeasonState=state;if(isLeagueView()&&!retry)render();
 // Callers that arrive while this load runs wait on it rather than returning early.
 let finish;state.done=new Promise(r=>finish=r);
 try{
  const shape=leagueShape(l),range=(from,to)=>Array.from({length:Math.max(0,to-from+1)},(_,i)=>from+i);
  // The demo has no history, so its one matchup repeats for the rest of the schedule.
  const load=weeks=>Promise.all(weeks.map(async week=>({week,matchups:S.data.demo?l.matchups.map(m=>({roster_id:m.roster_id,matchup_id:m.matchup_id})):await api.leagueWeek(l.league_id,week,{force,...(week>=S.data.week-1?{ttl:600000}:{})})})));
  const [past,future]=await Promise.all([S.data.demo?[]:load(range(shape.startWeek,Math.min(S.data.week,shape.playoffStart)-1)),load(range(S.data.week+1,shape.playoffStart-1))]);
  state.future=future;state.past=past;
 }catch(e){state.error=`Could not load this league’s schedule from Sleeper. ${e.message}`}
 finally{state.loading=false;if(S.leagueSeasonState===state&&(isLeagueView()||isTradeView()||S.view==='waivers'))render();finish()}
}
export function projectionStamp(rows){if(!projectionStamps.has(rows)){let latest=0,count=0;for(const p of Object.values(rows)){count++;if(p.updated_at>latest)latest=p.updated_at}projectionStamps.set(rows,`${count}:${latest}`)}return projectionStamps.get(rows)}
export function currentLeagueOutlook(){
 const l=league(),state=S.leagueSeasonState;if(!l||state?.key!==leagueSeasonKey(l)||!state.past)return null;
 const stamps=Object.entries(S.data.projections).map(([week,rows])=>[week,projectionStamp(rows)]),rosters=rosterKey(l);
 const key=JSON.stringify([state.key,S.data.nfl?.week,identity(state.past),identity(state.future),rosters,stamps,l.matchups.map(m=>[m.roster_id,m.matchup_id,m.points,m.custom_points,m.starters]),Object.entries(S.data.games).map(([team,g])=>[team,g.state,g.period,g.clock]),l.matchups.flatMap(m=>m.starters||[]).map(id=>S.data.players[id]?.injury_status||'')]);
 return leagueOutlooks.get(key,()=>leagueOutlook({league:l,players:S.data.players,past:state.past,future:state.future,currentWeek:S.data.week,isNflWeek:S.data.week===(S.data.nfl?.week??S.data.week),projections:S.data.projections,games:S.data.games,rosterMemo:(weeks,compute)=>rosterOutlooks.get(JSON.stringify([rosters,stamps,weeks]),compute)}));
}
export function leagueGate(head){
 const state=S.leagueSeasonState?.key===leagueSeasonKey()?S.leagueSeasonState:null;
 if(state?.loading&&state.retry)return head+empty(state.retry);
 if(!state||state.loading)return head+`<div class="empty" role="status"><h3>Loading the league’s season…</h3><p>Past weeks and the schedule are kept on this device, so this is quick next time.</p></div>`;
 if(state.error)return head+empty(state.error);
 const o=currentLeagueOutlook();
 if(!o.games&&!o.scheduledGames&&!o.live.games.length)return head+empty('This league has not started','Once Sleeper posts its schedule, the standings, odds and scores appear here.');
 return null;
}
export function leagueOutlookPage(){
 const head=analysisHeader('League outlook','Playoff odds, and how good every team is: by results so far and by the roster it has now.'),gate=leagueGate(head);if(gate)return gate;
 const o=currentLeagueOutlook(),{shape}=o,cut=i=>i===shape.playoffTeams-1&&i<o.rows.length-1?'playoff-cut':'';
 const me=o.rows.find(r=>r.mine),place=me?[...o.rows].sort((a,b)=>b.wins+b.ties/2-(a.wins+a.ties/2)||b.pf-a.pf).indexOf(me)+1:0,tier=p=>p>=.7?'good':p>=.35?'warn':'bad';
 const tile=(label,value,note,tone='')=>`<div class="league-tile tile-${tone}"><div class="eyebrow">${label}</div><strong>${value}</strong><span class="muted small">${note}</span></div>`;
 const mine=me?`<div class="league-tiles">${tile('YOUR PLAYOFF ODDS',chance(me.odds.playoff,o),o.regular?`${ordinal(place)} of ${shape.teams} now · top ${shape.playoffTeams} get in`:'Regular season over',tier(me.odds.playoff))}${tile('YOUR POWER RANK',`${ordinal(me.powerRank)}<small> of ${shape.teams}</small>`,`${fmt(me.rating)} points a week expected`,me.powerRank<=shape.playoffTeams?'good':'warn')}${tile('PROJECTED WINS',fmt(me.odds.wins),`${record(me)} so far · ${me.gamesLeft} game${me.gamesLeft===1?'':'s'} left`)}${o.current&&me.odds.ifWin!==null&&me.odds.ifLoss!==null?tile('THIS WEEK MATTERS',`${me.odds.ifWin-me.odds.ifLoss>=0?'+':''}${Math.round((me.odds.ifWin-me.odds.ifLoss)*100)}<small> points of odds</small>`,`${chance(me.odds.ifWin,o)} with a win · ${chance(me.odds.ifLoss,o)} with a loss`):me.schedule!==null?tile('SCHEDULE LEFT',`${ordinal(me.scheduleRank)}<small> hardest</small>`,`Opponents average ${fmt(me.schedule)} a week`):''}</div>`:'';
 const race=`<div class="panel table-wrap league-panel"><div class="section-bar"><div><h2>Playoff race</h2><p class="muted small">${!o.regular?'The regular season is over. This is how it finished.':`${shape.playoffTeams} of ${shape.teams} teams make it${shape.byes?`, the top ${shape.byes} get a bye`:''}. ${o.weeksLeft} week${o.weeksLeft===1?'':'s'} left, played out ${o.runs.toLocaleString()} times.`}${shape.medianGame?' This league also plays the median every week.':''}</p></div></div><table class="league-table"><thead><tr><th scope="col">TEAM</th><th scope="col">RECORD</th><th scope="col">PLAYOFFS</th>${shape.byes?'<th scope="col">BYE</th>':''}${o.regular?'<th scope="col">TITLE</th>':''}<th scope="col">PROJ. WINS</th>${o.current?'<th scope="col" title="Playoff odds if this week is won, and if it is lost">WIN / LOSE THIS WEEK</th>':''}<th scope="col">FINAL SEED</th></tr></thead><tbody>${o.rows.map((r,i)=>`<tr class="${cut(i)} ${r.mine?'mine':''}">${teamCell(r,`${fmt(r.pf)} PF`)}<td class="num">${record(r)}</td><td>${oddsBar(r.odds.playoff,o,`${r.team} make the playoffs in ${chance(r.odds.playoff,o)} of seasons`)}</td>${shape.byes?`<td class="num">${chance(r.odds.bye,o)}</td>`:''}${o.regular?`<td class="num">${chance(r.odds.title,o)}</td>`:''}<td class="num">${fmt(r.odds.wins)}</td>${o.current?`<td class="num swing">${r.odds.ifWin===null||r.odds.ifLoss===null?'—':`<span class="gain">${chance(r.odds.ifWin,o)}</span> / <span class="attention">${chance(r.odds.ifLoss,o)}</span>`}</td>`:''}<td><div class="seed-strip" role="img" aria-label="Most likely seed ${r.odds.seeds.indexOf(Math.max(...r.odds.seeds))+1}, average ${fmt(r.odds.seed)}">${r.odds.seeds.map((p,s)=>`<i class="${s===shape.playoffTeams-1?'seed-cut':''}" title="${ordinal(s+1)} seed: ${chance(p,o)}"><b style="opacity:${p<.005?0:Math.min(1,Math.sqrt(p)*1.3).toFixed(2)}"></b></i>`).join('')}</div></td></tr>`).join('')}</tbody></table></div>`;
 const power=[...o.rows].sort((a,b)=>a.powerRank-b.powerRank),rank=n=>`<span class="muted small">${ordinal(n)}</span>`;
 const rankings=`<div class="panel table-wrap league-panel"><div class="section-bar"><div><h2>Power rankings</h2><p class="muted small">Power blends results with the roster. ${o.games?`After ${o.games} week${o.games===1?'':'s'}, results carry ${Math.round(o.games/(o.games+8)*100)}% of it`:'No week has finished, so it is all roster for now'}; they earn more as the season goes on.</p></div></div><table class="league-table"><thead><tr><th scope="col">TEAM</th><th scope="col" title="Expected points a week from here on">POWER</th><th scope="col" title="Points a week in finished weeks">SO FAR</th><th scope="col" title="Best lineup by projection, averaged over the next few weeks">ROSTER</th><th scope="col" title="Every score against every other score, every week">ALL-PLAY</th><th scope="col" title="Head-to-head wins above what the same scores earn against the whole league">LUCK</th><th scope="col" title="Average power of the opponents left, hardest first">SCHEDULE LEFT</th></tr></thead><tbody>${power.map(r=>`<tr class="${r.mine?'mine':''}">${teamCell({...r,team:`${r.powerRank}. ${r.team}`},record(r))}<td class="num"><strong>${fmt(r.rating)}</strong></td><td class="num">${r.average===null?'—':`${fmt(r.average)} ${rank(r.seasonRank)}`}</td><td class="num">${r.roster?`${fmt(r.roster.points)} ${rank(r.rosterRank)}`:'—'}</td><td class="num">${r.games?`${r.allPlayWins}-${r.allPlayLosses}`:'—'}</td><td class="num ${r.luck>=.5?'gain':r.luck<=-.5?'attention':''}">${r.games?signed(r.luck):'—'}</td><td class="num">${r.schedule===null?'—':`${fmt(r.schedule)} ${rank(r.scheduleRank)}`}</td></tr>`).join('')}</tbody></table></div>`;
 const bySeason=S.leagueBasis==='season'&&o.games>0,basisPick=bySeason?(r=>r.games?r.byPosition:null):(r=>r.roster?.byPosition||null),unit=bySeason?'points a week':'projected points a week';
 const bars=bySeason?positionBars([...o.rows].sort((a,b)=>a.seasonRank-b.seasonRank),r=>r.byPosition,r=>r.average||0,unit):positionBars([...o.rows].filter(r=>r.roster).sort((a,b)=>a.rosterRank-b.rosterRank),r=>r.roster.byPosition,r=>r.roster.points,unit);
 const basisBar=`<div class="basis-bar"><div><h2>Team by team, position by position</h2><p class="muted small">${bySeason?'Measured by what each team’s starters have scored a week.':`Measured by each roster’s best lineup by projection, averaged over week${o.projectedWeeks.length===1?'':'s'} ${o.projectedWeeks.join(', ')||'—'}, so byes and injuries count.`}</p></div><div class="filters" role="group" aria-label="Measure teams by">${[['season','Season so far'],['roster','Roster ahead']].map(([id,label])=>`<button class="filter ${(bySeason?'season':'roster')===id?'active':''}" data-league-basis="${id}" aria-pressed="${(bySeason?'season':'roster')===id}" ${id==='season'&&!o.games?'disabled':''}>${label}</button>`).join('')}</div></div>`;
 const chart=bySeason?o.depth.season:o.depth.roster;
 const strength=basisBar+`<div class="panel"><h2>Team shapes</h2><p class="muted small">Each corner is a position. The grey ring is the league average, so a corner outside it is a strength and one inside it is a hole.</p>${teamRadar(o,basisPick,unit)}</div>`+
  (chart?`<div class="defense-legend" aria-label="Rank in the league at that spot"><span>${bySeason?'Points a game by each team’s best players':'Projected points a game by each team’s best players'}, colored by rank in the league. Click one of your spots to look for an upgrade there.</span>${[['strong','Top fifth'],['good','Above average'],['neutral','Middle'],['weak','Below average'],['poor','Bottom fifth']].map(([t,label])=>`<span class="defense-key defense-${t}">${label}</span>`).join('')}</div>${depthTable(o,chart,unit)}`:'')+
  `<div class="split league-split"><div class="panel"><h2>Where the points come from</h2><p class="muted small">${bySeason?'What each team’s starters have scored a week, by position.':'Each roster’s best lineup, by position.'}</p>${bars}</div><div class="panel"><h2>Results against roster</h2><p class="muted small">Right is a stronger roster, up is more points so far. The lines are the league averages.</p>${strengthScatter(o.rows)||'<p class="muted small">This fills in once a week has finished.</p>'}</div></div>`;
 const tone=d=>d<=-25?'poor':d<=-10?'weak':d<10?'neutral':d<25?'good':'strong';
 const weekly=o.games?`<div class="panel table-wrap defense-table-wrap league-panel flush"><table class="week-table season-table"><thead><tr><th scope="col">TEAM</th>${o.weeks.map(w=>`<th scope="col">WEEK ${w.week}</th>`).join('')}<th scope="col">AVG.</th><th scope="col">PF</th><th scope="col">PA</th></tr></thead><tbody>${[...o.rows].sort((a,b)=>a.seasonRank-b.seasonRank).map(r=>`<tr><th scope="row" class="season-player"><strong>${esc(r.team)}</strong><div class="muted small">${record(r)}</div></th>${o.weeks.map(w=>{const s=r.scores.find(s=>s?.week===w.week);return s?`<td class="defense-cell season-cell defense-${tone(s.diff)}" title="${signed(s.diff)} against a league average of ${fmt(w.average)}"><strong>${fmt(s.points)}</strong><div class="small">${signed(s.diff)}</div></td>`:'<td class="defense-cell season-cell muted">—</td>'}).join('')}<td class="defense-cell"><strong>${fmt(r.average)}</strong></td><td class="defense-cell">${fmt(r.pf)}</td><td class="defense-cell">${fmt(r.pa)}</td></tr>`).join('')}</tbody></table></div>`:'';
 return head+mine+race+rankings+strength+(weekly?`<div class="defense-legend" aria-label="Points against the league average that week"><span>Weekly scores against the league average</span>${[['poor','−25 or worse'],['weak','−25 to −10'],['neutral','Within 10'],['good','+10 to +25'],['strong','+25 or more']].map(([t,label])=>`<span class="defense-key defense-${t}">${label}</span>`).join('')}</div>`+weekly:'')+
 `<details class="data-details"><summary>How the odds work</summary><p>The rest of the schedule is played out ${o.runs.toLocaleString()} times. Every team gets a power rating in points a week: results so far blended with the best lineup its current roster projects to field. Each run first draws how good every team really is around that rating, then draws every remaining score with a weekly swing of about ${fmt(o.spread,0)} points, the spread seen in this league. ${o.current?'This week uses the live score plus projections for players yet to play. ':''}Seeds go by record, then points for${shape.divisions?', with division winners first':''}${shape.medianGame?', and every week adds a win or loss against the league median':''}. The title column plays a single-game bracket on the same ratings. Trades, injuries and waiver moves will change all of this, and early in the season the honest answer is that nobody is far from a coin flip.</p></details>`;
}
